insert into public.master_requirements (id,title,statement,source_basis,iat_coverage,evidence,sa_output,moo_output,platform_req,data_entities,escalation_rule,priority,sort) values
('MR-01','Project objective: validated actionable MOO','Create one integrated, evidence-based operating framework linking CDRRMO institutional functions and EOC incident coordination.','Inception Report Objectives 1–5; IAT v1.1 purpose/use','All 140 indicators (125 core in Parts A–B; 15 interface in Part C)','Validated evidence register; scored baseline; priority gaps','Executive Summary; methodology; consolidated findings; priority actions','Integrated MOO architecture; procedures, standards, roles, forms and update mechanism','Role-based assessment workflow; evidence-first scoring; traceability view','Assessment cycle; evidence; scores; gaps; actions; MOO traceability; document versions','Applies to the whole assessment','Critical',1),
('MR-02','Functional Area 1','Define mandate, organization, authority, delegation, roles, coordination and accountability.','MOO Functional Area 1; A1, A2, A10','A1.1–A1.8; A2.1–A2.10; A10.1–A10.3','Legal instruments, organogram, plantilla, rosters, MOAs, reporting records, skills inventory','Governance/institutional findings','Ch.1–2; Ch.9 partnerships; role/JD annexes','Governance module; role matrix; approval workflow','organizations; offices; positions; authorities; partnerships; declarations; skills_inventory','High when mandatory legal/role gaps score below 3','High',2),
('MR-03','Functional Area 2','Maintain current multi-hazard risk intelligence, prevention/mitigation and risk-informed planning.','MOO Functional Area 2; A3, A5; Part C C1–C3','A3.1–A3.7; A5.1–A5.9; interface C1.1–C1.4, C2.1–C2.3, C3.1–C3.3','Plans, hazard maps, CDRA, GIS/data records, critical-facility dependency map, dataset version dates; lead-office records for Part C','Risk and planning baseline; Part C interface results','Ch.3 Planning; Ch.7 Knowledge Management','GIS/risk dashboard; document/version control; failure-chain view','plans; hazards; risk_scenarios; gis_layers; datasets; critical_facilities; facility_dependencies','Risk-informed prioritization','High',3),
('MR-04','Functional Area 3','Establish preparedness, contingency planning, capacity development, drills and readiness standards.','MOO Functional Area 3; A3, A7, B7; Part C C5','A3.3–A3.6; A7.1–A7.9; B7.2–B7.6; interface C5.1','CPs, PSCP, training, refresher and drill records, EC audits, stock records, welfare-check drills','Preparedness capacity and readiness gaps','Ch.3 Planning; Ch.4; Ch.6 Capacity; EOC Ch.8–9','Preparedness dashboard; training/exercise calendar; refresher tracking','plans; training; exercises; evacuation_centers; inventories; welfare_checks','High for untested mandatory readiness','High',4),
('MR-05','Functional Area 4','Define EOC activation/deactivation, incident management, ICS interface, escalation, transition and anticipatory action.','MOO Functional Area 4; B1, B4, B7.1, A8; A1.8; Part C C4','A1.8; A8.1–A8.9; B1.1–B1.5; B4.1–B4.2; B7.1; interface C4.1–C4.4','ICS EO, IMT roster, activation matrix/logs, EOC organogram and roster with alternates, approved EOC SOPs, PDRA records, AA protocols, sector AA plans','EOC/response readiness baseline','Ch.4 Response; EOC Ch.1–2; EOC Ch.7','Activation wizard; operational-period workflow; ICS/EOC role view; AA protocol checklist','activation_levels; activation_events; incidents; imt_rosters; aa_protocols','Immediate escalation for mandatory activation/ICS/AA gaps','Critical',5),
('MR-06','Functional Area 5','Operate hazard monitoring, warning thresholds, last-mile dissemination, emergency communications and public information.','MOO Functional Area 5; A6, B3','A6.1–A6.7; B3.1–B3.6','EWS logs, warning matrix, test logs, comms inventory, directory, declaration/AA advisory templates','Warning/communications findings','Ch.4; EOC Ch.3–4; EOC Ch.5','Warning composer; dissemination log; channel status','warning_systems; thresholds; messages; channels; communication_assets; network_tests; advisory_templates','Life-safety priority; weight-3 mandatory gaps','Critical',6),
('MR-07','Functional Area 6','Maintain situational awareness, information management, GIS/COP, SitReps and reporting flows.','MOO Functional Area 6; B5, A5, A10','A5.1–A5.9; A10.3–A10.8; B5.1–B5.7','GIS layers, SitReps, logs, monitoring records, reports, 45-day RA 12287 reports, citizen-report intake logs','Information-system and reporting baseline','Ch.7; EOC Ch.5–6','Common Operating Picture; reporting workflow; audit trail; verified citizen-report intake','sit_reps; cop_layers; event_logs; reports; hazard_feeds; citizen_reports; declaration_reports','Data quality/completeness and timeliness','High',7),
('MR-08','Functional Area 7','Provide resource, logistics and emergency support management, including procurement, stockpiling, prepositioning and mutual aid.','MOO Functional Area 7; A4, A7, A8, B6','A4.1–A4.9; A7.5; A8.3; A8.8; B6.1–B6.6','Budget/fund records incl. AA line, procurement SOPs, inventories, resource requests, MOAs, supplier agreements','Resource and financial capacity findings','Ch.5 Financing; EOC Ch.6–7','Resource request/approval/tracking; logistics dashboard; AA fund tracker','budgets; resources; warehouses; resource_requests; mutual_aid; resource_commitments; aa_fund_allocations','High for legal/fund/resource bottlenecks','High',8),
('MR-09','Functional Area 8','Protect responders and ensure welfare, fatigue management, inclusion and safe emergency operations.','MOO Functional Area 8; A2, A7, B4','A2.7; A7.6; B4.3–B4.6','Insurance/PPE/MHPSS records, inclusion plans, sector representatives'' confirmation, rosters, welfare procedures','Responder safety and inclusion findings','Ch.2/4; EOC Ch.5','Duty/welfare alerts; protected role data; inclusion checklist','responder_profiles; welfare_records; duty_rosters; inclusion_controls','Life-safety and duty-of-care gaps','Critical',9),
('MR-10','Functional Area 9','Ensure digital continuity, cybersecurity, alternate EOC capability, backup power/connectivity and protected data.','MOO Functional Area 9; A3.4, A5.5, B2, B3','A3.4; A5.5; B2.1–B2.7; B3.3–B3.6','PSCP, site assessment, generator/failover tests, privacy/security records','Continuity/cyber resilience baseline','EOC Ch.3–4; EOC Ch.7','Continuity status; test history; incident/audit logs','facilities; alternate_eoc; backups; cybersecurity_controls; continuity_plans','High/critical for single points of failure','Critical',10),
('MR-11','Functional Area 10','Institutionalize recovery, learning, M&E, AARs, improvement tracking and annual reassessment.','MOO Functional Area 10; A9, A10, B7','A9.1–A9.5; A10.4–A10.9; B7.3–B7.6','Recovery plans and pre-disaster recovery framework, AARs, M&E reports, recognition results, exercise records, learning exchanges','Recovery and continuous-improvement findings','Ch.7–8; EOC Ch.8–9','Improvement cycle; annual reassessment; change history','recovery_plans; aar_records; lessons_learned; improvement_actions; assessment_cycles; learning_exchanges','Trend and closure tracking','High',11),
('MR-12','Cross-cutting evidence standard','Every score must be traceable to evidence; interviews/FGDs alone cannot support scores above 2. Part C evidence comes from the lead office under the same rule.','IAT v1.1 methodology §§5–6','All 140','Evidence records with source, date, verification method and validation status','Evidence-quality narrative','Evidence annex; validation notes','Evidence drawer; score/evidence linkage; immutable history','evidence_records; validation_records; documents','Evidence quality gates','Critical',12),
('MR-13','Cross-cutting scoring and priority engine','Automate maturity, mandatory compliance and gap priority consistently across cycles. The Institutional Maturity Index covers Parts A–B only; Part C produces a separate Interface Index using the Good Practice factor.','IAT v1.1 methodology §5 (incl. §5.5 Interface Index)','All scored indicators; IMI = 125 core; Interface Index = 15 Part C','Score, weight, type, evidence strength, priority calculation','Dashboard and compliance summary; Interface Index','Action Plan; priority actions','Explainable scoring engine; separate index streams','assessment_responses; score_history; gaps; index_results','Formula-driven','Critical',13),
('MR-14','Cross-cutting traceability','Each indicator gap must route to a required improvement, responsible owner (lead office for Part C), MOO chapter/SOP and digital requirement.','IAT purpose/use; Inception Report; IAT v1.1 Annex G','All 140','Indicator-to-gap-to-action-to-MOO linkage','MOO implications chapter-by-chapter (§10)','MOO requirements and SOP/form list','Traceability explorer','indicator_moo_links; gaps; actions; moo_chapters; sops; interface_offices','Closed-loop improvement','Critical',14),
('MR-15','Cross-cutting governance, privacy and annual reuse','Protect assessment information, limit personal data (no beneficiary or CBMS personal data copied into the assessment), maintain City-controlled storage, audit changes and support annual self-assessment.','IAT QA/Ethics/Data Privacy; RA 10173; annual self-assessment objective','All 140','Access controls, audit logs, privacy controls, versioned records','Method limitations/privacy statement','MOO governance/update mechanism','RBAC/RLS; audit trail; versioning; annual cycle cloning','users; roles; audit_logs; document_versions; assessment_cycles','Privacy breach risk is always High','Critical',15),
('MR-16','Statutory: RA 12287 and IRR (anticipatory action)','Be ready to request, declare, implement, fund, lift and report a State of Imminent Disaster, and to take anticipatory action within the lead time, including city-level early action for short-lead-time hazards (flash floods, landslides).','RA 12287; IRR signed 14 Sep 2026 (Rules II–VII); IAT v1.1 Annex G §5','A1.8; A2.8; A2.9; A4.6; A5.8; A6.2; A6.7; A7.6; A8.6; A8.8; A8.9; A10.8; B1.2; B6.6; C2.1; C2.2; C2.3; C3.3; C4.1; C4.2; C4.3; C4.4','SOP and EO templates; RDRRMC request records; AA protocols; LDRRMFIP AA line; advisory templates; targeting guidelines; 45-day reports','§5 Readiness under RA 12287','MOO Ch.1 declaration procedure; MOO Ch.4 AA protocols; MOO Ch.5 AA funding; MOO Ch.7 reporting; EOC Ch.2 anticipatory posture','Declaration workflow (PDRA → CDRRMC → RDRRMC 24-hour reply → Mayor''s EO → lifting); AA checklist by hazard and lead time; AA fund tracker with 30%/70% tranche rule; 45-day report generator','declarations; pdras; aa_protocols; aa_triggers; prepositioning_orders; aa_fund_allocations; beneficiary_targeting; declaration_reports','Escalate weight-3 Mandatory AA gaps to the Mayor and CDRRMC before typhoon season','Critical',16),
('MR-17','Interface indicators (Part C)','Assess, separately from the CDRRMO''s own index, city systems owned by other offices that the CDRRMO depends on, and route each gap to the named lead office.','IAT v1.1 Part C; UNDRR Scorecard; RA 12287 IRR Rule IV Secs. 4, 8–10','C1.1–C5.1 (15 indicators)','Lead-office records; short KIIs with lead offices','§6 Results for Part C, by lead office','MOO Ch.3 and Ch.9 coordination arrangements; EOC Ch.4 and Ch.7 sector desks','Lead-office assignment; separate Interface Index; inter-office action tracking','interface_offices; interface_responses; inter_office_actions','High only at weight 3 and score ≤1 (Good Practice factor)','High',17),
('MR-18','Framework alignment: UNDRR Disaster Resilience Scorecard','Keep each Scorecard-derived indicator traceable to its DRSC criterion so results can feed MCR2030 and Sendai reporting; Scorecard criteria not adopted stay for a city-wide Scorecard workshop and are not scored.','UNDRR DRSC Detailed Level Assessment (2017); IAT v1.1 Crosswalk','A2.10; A4.9; A5.7; A5.8; A5.9; A7.6; A7.8; A7.9; A9.5; A10.2; A10.9; B5.7; B6.6; C1.1; C1.2; C1.3; C1.4; C2.1; C2.2; C2.3; C3.1; C3.2; C5.1','DRSC reference in each indicator; Framework_Crosswalk sheet','§2 Background and method; Crosswalk annex','MOO Ch.7 M&E and reporting','Framework crosswalk view; external framework tags on indicators','framework_refs; indicator_framework_links','Deferred criteria are not scored','Medium',18)
