insert into public.protocol_templates (id,code,title,purpose,trigger_text,document_id,owner_role,category,status,template_rev) values
('55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,'PR-DUTY-HANDOVER','Duty shift handover','Keep 24/7 operations continuous between shifts.','Every change of duty shift at the Operations Center.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'daily_operations','draft',1),
('f726b603-075b-5232-a798-5054f4d3e64d'::uuid,'PR-WARNING-DISSEM','Warning dissemination','Move a hazard bulletin to every at-risk purok, in a form people understand.','On receipt of a PAGASA, PHIVOLCS or MGB bulletin or advisory that affects Ormoc.','33665e28-8c73-5cda-912b-4ddcf179ea16'::uuid,'duty_officer'::public.app_role,'warning','draft',1),
('fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,'PR-EOC-ACTIVATE','EOC activation (Blue or Red)','Stand up the EOC quickly with the right people and records.','When the EOC is raised to Blue or Red as directed by the City Mayor (Responsible Official), or by the EOC Manager under the approved activation protocol.','33665e28-8c73-5cda-912b-4ddcf179ea16'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1),
('c79bca15-67f0-538e-9e52-8d969da30076'::uuid,'PR-PDRA','Pre-disaster risk assessment (PDRA)','Decide, from the forecast and local exposure, whether to monitor, act early or request a declaration.','When a forecast hazard may affect Ormoc.','33665e28-8c73-5cda-912b-4ddcf179ea16'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1),
('5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,'PR-SOID-REQUEST','State of Imminent Disaster: request and declaration','Follow RA 12287, its IRR and SOP GOV-05 from the PDRA to the Mayor''s Executive Order.','When the PDRA classifies the projected impact as severe or its equivalent (including where IRR Rule II Sec. 4 factors support that classification below the thresholds) and there is enough lead time to carry out anticipatory action.','f66e432b-487f-5434-a8eb-de42ef848a67'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1),
('f99e18a5-6514-56f9-8bf6-dc31df80cd6f'::uuid,'PR-SOC-DECLARE','State of Calamity: assessment, declaration and lifting','Follow RA 10121 Sec. 16 and SOP GOV-04: the Sangguniang Panlungsod declares or lifts, on the CDRRMC''s recommendation.','When damage and needs reports indicate that a State of Calamity may be warranted.','e715b34c-ec5f-5f4c-b34c-378225a2156c'::uuid,'cdrrmo_head'::public.app_role,'council','draft',1),
('7bcbdc7d-00f9-516a-a030-e4d89022be09'::uuid,'PR-FLASHFLOOD-EARLY','Flash flood and landslide early action','Act on short-lead hazards that cannot wait for a declaration.','When rainfall or river readings reach the City''s early-action thresholds for the Anilao–Malbasag system or upland barangays.','33665e28-8c73-5cda-912b-4ddcf179ea16'::uuid,'duty_officer'::public.app_role,'anticipatory_action','draft',1),
('90cb1850-de66-5a00-a46c-47db38ebdc84'::uuid,'PR-SITREP-CYCLE','SitRep cycle','Produce a verified SitRep on schedule every operational period.','At each scheduled SitRep time during an activation.','a0cad148-d5ee-5805-bf81-4b86fbf1aeac'::uuid,'eoc_staff'::public.app_role,'reporting','draft',1),
('a37bb249-1b6f-585a-8b12-bc80b742cc63'::uuid,'PR-CDRRMC-MEETING','CDRRMC meeting (secretariat)','Run the Council meeting and keep its records complete.','Quarterly, and whenever the Chair calls a special meeting.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'duty_officer'::public.app_role,'council','draft',1),
('33dfaee2-77a8-5b13-956e-bb805634d0b1'::uuid,'PR-LIFT-REPORT','Lifting and 45-day report','Lift a State of Imminent Disaster correctly and report to OCD on time.','When the hazard occurs or the PDRA shows the projected impacts will not be met.','aec20d50-301b-57ce-87d4-64154502a0ef'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1)
insert into public.protocol_steps (id,template_id,seq,instruction,is_critical,requires_note,due_offset_minutes) values
('7b4f30ce-80a5-50b8-8b3f-9b665f04d2e9'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,1,'Read the logbook entries since the last handover',false,false,0),
('f76135e7-704d-5211-871a-18639ce440a5'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,2,'Review open incidents, resource requests and pending barangay reports',true,false,5),
('de1d96cd-2acb-5d95-abc5-7a2f9845a9bc'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,3,'Check the latest PAGASA and PHIVOLCS bulletins and record any change',true,true,10),
('20b4a938-cb8c-5acd-afa3-07c45e6deb79'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,4,'Run the radio net check with the barangays scheduled for this shift',true,true,20),
('891f3462-6f4b-5649-aeb7-7a38fa30e2c8'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,5,'Check generator fuel, UPS and backup internet status',false,true,25),
('d0c39b49-78f2-550e-a961-f96280cbfbc5'::uuid,'55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,6,'Record handover notes and sign off with the incoming duty officer',true,true,30),
('76cbabd3-218b-5e4a-b8e5-6ace194a0978'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,1,'Log the bulletin: issuer, number, time issued, hazard and areas',true,true,0),
('e28ac733-4b98-54d8-a8f5-1e669cff5cd4'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,2,'Check it against the City warning-to-action matrix and note the matching alert and actions',true,true,10),
('7e03ea6d-103e-5725-8cc8-0ea0143c0fb3'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,3,'Notify the EOC Manager and CDRRMO Head; record the instruction received',true,true,15),
('971261f1-d074-511d-b15a-233304fce743'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,4,'Issue the advisory in Cebuano, with Filipino/English and accessible formats as needed',true,false,30),
('e8e4c9bb-70ad-500b-a769-7b65168d381a'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,5,'Send through every channel: emergency cell broadcast/SMS, radio, social media, barangay officials',true,true,40),
('40b627a7-0af1-5cf1-83e7-843c0c0c5bd3'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,6,'Confirm receipt from riverine, coastal and upland barangays first, then the rest',true,true,60),
('d5a35cb5-9820-53c5-946d-d65fb0a32b7f'::uuid,'f726b603-075b-5232-a798-5054f4d3e64d'::uuid,7,'Log barangays that did not confirm and assign follow-up',false,true,75),
('cd64827e-a96b-5fcd-bfb7-3ed7d5ecdc54'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,1,'Record the level change and reason in the platform (logs it automatically). If no device can connect, write it in the paper logbook with the time and enter it once connected',true,false,0),
('c84e068c-60c3-51af-925f-532b4dc62505'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,2,'Notify CDRRMC members, cluster leads and liaison desks of the activation',true,true,15),
('95d5a158-d9b2-5721-936f-7119e10924f2'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,3,'Fill EOC positions from the roster, with alternates',true,true,30),
('d83ee728-0913-5aea-a8f9-368e3ba41809'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,4,'Run the communications check on all redundant channels',true,true,30),
('6ff329f4-ff72-5d9a-a662-4161c775394b'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,5,'Set the operational period and the SitRep schedule',true,true,45),
('14c130f6-09a6-51db-83aa-8d96fe5b15e2'::uuid,'fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,6,'Brief the Mayor on the situation and decisions needed',true,true,60),
('4f17821c-f260-5257-b5e2-8df477adf587'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,1,'Convene the PDRA core group and record attendance by office',true,false,0),
('309ebaee-2082-5388-a60c-8800074ec960'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,2,'Review the forecast: hazard, expected impact time, areas, impact level',true,true,15),
('384773c7-bacd-59eb-840e-b56a87ee9538'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,3,'Identify exposed barangays, vulnerable groups, critical facilities and possible cascading hazards',true,true,30),
('34aaaca7-ac10-5dbf-a3fc-234b01e2a2bf'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,4,'Classify the projected impact and compute the lead time left',true,false,45),
('597c0c29-02c6-5e0d-a3c9-b92156d8d26a'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,5,'Decide: monitor, city early action, or request a State of Imminent Disaster; record the basis',true,true,60),
('8e4fbed1-dcff-5b4f-b19e-6f001d3d5ab1'::uuid,'c79bca15-67f0-538e-9e52-8d969da30076'::uuid,6,'Record the PDRA in the platform and brief the CDRRMO Head',true,false,75),
('42996283-5f6d-53c0-9fbf-0a4222ecdcdb'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,1,'Record the official forecast: issuer, time issued, validity, areas, expected impact time, and both the lead time from issuance and the time left before impact',true,true,0),
('98934062-2853-5d92-9d47-c525404bbfff'::uuid,'5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,2,'Attach the PDRA summary: exposure, projected severity, cascading hazards, sector needs, and any IRR Rule II Sec. 4 factors relied on',true,true,10),
